{"file_path":"src/address.js","content":"/**
 * Cell addresses: one or two letters naming a column, one to three digits
 * naming a row of at least one. Addresses are upper-cased when read, so `a1`
 * and `A1` name the same cell.
 */

const ADDRESS = /^[A-Z]{1,2}(\d{1,3})$/

/** Parse `text` as an address. Returns `{ col, row, key }` or `null`. */
export function parseAddress(text) {
  const upper = text.toUpperCase()
  const match = ADDRESS.exec(upper)
  if (match === null) return null
  const row = Number(match[1])
  if (row < 1) return null
  const letters = upper.slice(0, upper.length - match[1].length)
  let col = 0
  for (const letter of letters) col = col * 26 + (letter.charCodeAt(0) - 64)
  return { col, row, key: upper }
}

/** The canonical text of the cell at `col` (one based) and `row`. */
export function formatAddress(col, row) {
  let letters = ''
  let n = col
  while (n > 0) {
    const rem = (n - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    n = Math.floor((n - 1) / 26)
  }
  return letters + String(row)
}

/** Order two parsed addresses by column and then by row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

