{"file_path":"src/parser.js","content":"/**
 * The formula grammar. `parseFormula` turns the body of a formula (everything
 * after the leading `=`) into a syntax tree, or reports that the grammar does
 * not accept it.
 */

const OPERATORS = ['<>', '<=', '>=', '^', '*', '/', '+', '-', '=', '<', '>']

class SyntaxFailure extends Error {}

function fail() {
  throw new SyntaxFailure('grammar')
}

/** Split `source` into tokens, skipping the spaces and tabs between them. */
function tokenize(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const ch = source[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < source.length && source[j] >= '0' && source[j] <= '9') j += 1
      if (source[j] === '.' && source[j + 1] >= '0' && source[j + 1] <= '9') {
        j += 1
        while (j < source.length && source[j] >= '0' && source[j] <= '9') j += 1
      }
      tokens.push({ type: 'number', text: source.slice(i, j) })
      i = j
      continue
    }
    if (isLetter(ch)) {
      let j = i
      while (j < source.length && (isLetter(source[j]) || isDigit(source[j]))) j += 1
      tokens.push({ type: 'word', text: source.slice(i, j) })
      i = j
      continue
    }
    if (ch === '(' || ch === ')' || ch === ',' || ch === ':') {
      tokens.push({ type: ch, text: ch })
      i += 1
      continue
    }
    const operator = OPERATORS.find((op) => source.startsWith(op, i))
    if (operator === undefined) fail()
    tokens.push({ type: 'operator', text: operator })
    i += operator.length
  }
  return tokens
}

function isLetter(ch) {
  return ch !== undefined && ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z'))
}

function isDigit(ch) {
  return ch !== undefined && ch >= '0' && ch <= '9'
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek() {
    return this.tokens[this.at]
  }

  next() {
    const token = this.tokens[this.at]
    if (token === undefined) fail()
    this.at += 1
    return token
  }

  isOperator(...texts) {
    const token = this.peek()
    return token !== undefined && token.type === 'operator' && texts.includes(token.text)
  }

  expect(type) {
    const token = this.next()
    if (token.type !== type) fail()
    return token
  }

  // The comparisons, loosest and left grouping.
  parseExpression() {
    let left = this.parseAdditive()
    while (this.isOperator('=', '<>', '<', '<=', '>', '>=')) {
      const op = this.next().text
      const right = this.parseAdditive()
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.isOperator('+', '-')) {
      const op = this.next().text
      const right = this.parseMultiplicative()
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.isOperator('*', '/')) {
      const op = this.next().text
      const right = this.parsePower()
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  // `^` groups to the right and binds looser than a leading sign.
  parsePower() {
    const base = this.parseUnary()
    if (this.isOperator('^')) {
      this.next()
      return { kind: 'binary', op: '^', left: base, right: this.parsePower() }
    }
    return base
  }

  parseUnary() {
    if (this.isOperator('-', '+')) {
      const op = this.next().text
      return { kind: 'unary', op, operand: this.parseUnary() }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.next()
    if (token.type === 'number') return { kind: 'number', value: Number(token.text) }
    if (token.type === '(') {
      const inner = this.parseExpression()
      this.expect(')')
      return { kind: 'group', inner }
    }
    if (token.type !== 'word') fail()
    const upper = token.text.toUpperCase()
    const after = this.peek()
    if (after !== undefined && after.type === '(') {
      this.next()
      const args = []
      if (this.peek() !== undefined && this.peek().type === ')') {
        this.next()
      } else {
        for (;;) {
          args.push(this.parseExpression())
          const sep = this.next()
          if (sep.type === ')') break
          if (sep.type !== ',') fail()
        }
      }
      return { kind: 'call', name: upper, args }
    }
    if (upper === 'TRUE') return { kind: 'boolean', value: true }
    if (upper === 'FALSE') return { kind: 'boolean', value: false }
    if (after !== undefined && after.type === ':') {
      this.next()
      const end = this.expect('word')
      const following = this.peek()
      if (following !== undefined && following.type === '(') fail()
      return { kind: 'range', from: token.text, to: end.text }
    }
    return { kind: 'reference', text: token.text }
  }
}

/**
 * Parse the body of a formula. Returns the syntax tree, or `null` when the
 * grammar does not accept the body.
 */
export function parseFormula(body) {
  try {
    const parser = new Parser(tokenize(body))
    const tree = parser.parseExpression()
    if (parser.at !== parser.tokens.length) fail()
    return tree
  } catch (error) {
    if (error instanceof SyntaxFailure) return null
    throw error
  }
}
"}

