{"file_path":"src/evaluate.js","content":"/**
 * The sheet: the cells read from the input, the value of each one, and the
 * cells each one names directly.
 */

import { compareAddresses, formatAddress, parseAddress } from './address.js'
import { parseFormula } from './parser.js'
import {
  CYCLE,
  DIV0,
  ERR,
  NAME,
  REF,
  asNumber,
  boolean,
  error,
  finite,
  compareValues,
  isError,
  literalValue,
  number,
} from './values.js'

const ARITIES = {
  SUM: [1, Infinity],
  MIN: [1, Infinity],
  MAX: [1, Infinity],
  COUNT: [1, Infinity],
  AVG: [1, Infinity],
  ABS: [1, 1],
  IF: [3, 3],
}

export class Sheet {
  constructor() {
    /** Declared cells, keyed by canonical address, in declaration order. */
    this.cells = new Map()
    this.cache = new Map()
    this.inProgress = new Set()
  }

  /** Declare the cell at the parsed `address` with the given `content`. */
  declare(address, content) {
    const tree = content.startsWith('=') ? parseFormula(content.slice(1)) : undefined
    this.cells.set(address.key, { address, content, tree })
  }

  has(key) {
    return this.cells.has(key)
  }

  /** The declared cells, in ascending column and then ascending row order. */
  ordered() {
    return [...this.cells.values()].sort((a, b) => compareAddresses(a.address, b.address))
  }

  /** The value of the cell at the canonical address `key`. */
  valueAt(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.inProgress.has(key)) return CYCLE
    const cell = this.cells.get(key)
    if (cell === undefined) return number(0)
    if (cell.tree === undefined) {
      const value = literalValue(cell.content)
      this.cache.set(key, value)
      return value
    }
    this.inProgress.add(key)
    let value
    try {
      value = cell.tree === null ? ERR : this.evaluate(cell.tree)
    } finally {
      this.inProgress.delete(key)
    }
    this.cache.set(key, value)
    return value
  }

  /** The value of one syntax tree node. */
  evaluate(node) {
    switch (node.kind) {
      case 'number':
        return number(node.value)
      case 'boolean':
        return boolean(node.value)
      case 'group':
        return this.evaluate(node.inner)
      case 'reference': {
        const address = parseAddress(node.text)
        return address === null ? REF : this.valueAt(address.key)
      }
      case 'range':
        // A range is only meaningful directly as a function argument.
        return ERR
      case 'unary':
        return this.evaluateUnary(node)
      case 'binary':
        return this.evaluateBinary(node)
      default:
        return this.evaluateCall(node)
    }
  }

  evaluateUnary(node) {
    const operand = asNumber(this.evaluate(node.operand))
    if (isError(operand)) return operand
    return node.op === '-' ? finite(-operand.number) : finite(operand.number)
  }

  evaluateBinary(node) {
    const comparison = ['=', '<>', '<', '<=', '>', '>='].includes(node.op)
    if (comparison) {
      const left = this.evaluate(node.left)
      if (isError(left)) return left
      const right = this.evaluate(node.right)
      if (isError(right)) return right
      const order = compareValues(left, right)
      switch (node.op) {
        case '=':
          return boolean(order === 0)
        case '<>':
          return boolean(order !== 0)
        case '<':
          return boolean(order < 0)
        case '<=':
          return boolean(order <= 0)
        case '>':
          return boolean(order > 0)
        default:
          return boolean(order >= 0)
      }
    }
    const left = asNumber(this.evaluate(node.left))
    if (isError(left)) return left
    const right = asNumber(this.evaluate(node.right))
    if (isError(right)) return right
    const a = left.number
    const b = right.number
    switch (node.op) {
      case '+':
        return finite(a + b)
      case '-':
        return finite(a - b)
      case '*':
        return finite(a * b)
      case '/':
        return b === 0 ? DIV0 : finite(a / b)
      default:
        return finite(a ** b)
    }
  }

  /** The values one argument contributes: a range contributes every cell. */
  argumentValues(node) {
    if (node.kind !== 'range') return [this.evaluate(node)]
    const cells = rangeCells(node)
    if (cells === null) return [REF]
    return cells.map((key) => this.valueAt(key))
  }

  evaluateCall(node) {
    const arity = ARITIES[node.name]
    if (arity === undefined) return NAME
    if (node.args.length < arity[0] || node.args.length > arity[1]) return ERR
    if (node.name === 'IF') return this.evaluateIf(node)
    const values = node.args.flatMap((arg) => this.argumentValues(arg))
    if (node.name === 'COUNT') {
      for (const value of values) if (isError(value)) return value
      return number(values.filter((value) => value.kind === 'number').length)
    }
    const numbers = []
    for (const value of values) {
      const n = asNumber(value)
      if (isError(n)) return n
      numbers.push(n.number)
    }
    switch (node.name) {
      case 'SUM':
        return finite(numbers.reduce((a, b) => a + b, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
      default:
        return finite(Math.abs(numbers[0]))
    }
  }

  evaluateIf(node) {
    const condition = this.argumentValues(node.args[0])
    let taken = null
    for (const value of condition) {
      const n = asNumber(value)
      if (isError(n)) return n
      if (taken === null) taken = n.number !== 0
    }
    const branch = this.argumentValues(taken ? node.args[1] : node.args[2])
    for (const value of branch) if (isError(value)) return value
    return branch.length === 0 ? number(0) : branch[0]
  }

  /** The cells the content of `cell` names directly, ranges expanded. */
  dependencies(cell) {
    if (cell.tree === undefined || cell.tree === null) return []
    const found = new Map()
    collect(cell.tree, found)
    return [...found.values()]
      .sort(compareAddresses)
      .map((address) => formatAddress(address.col, address.row))
  }
}

/** The canonical addresses a range covers, or `null` when it is out of range. */
function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const keys = []
  for (let col = Math.min(from.col, to.col); col <= Math.max(from.col, to.col); col += 1) {
    for (let row = Math.min(from.row, to.row); row <= Math.max(from.row, to.row); row += 1) {
      keys.push(formatAddress(col, row))
    }
  }
  return keys
}

function collect(node, found) {
  switch (node.kind) {
    case 'reference': {
      const address = parseAddress(node.text)
      if (address !== null) found.set(address.key, address)
      break
    }
    case 'range': {
      const from = parseAddress(node.from)
      const to = parseAddress(node.to)
      if (from === null || to === null) break
      for (let col = Math.min(from.col, to.col); col <= Math.max(from.col, to.col); col += 1) {
