/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'

import { parseAddress } from './address.js'
import { Sheet } from './evaluate.js'
import { formatValue } from './values.js'

class Failure extends Error {}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** Split the sheet into its lines, dropping the tail a final newline leaves. */
function sheetLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/** Read the sheet, reporting the first line that is not well formed. */
function readSheet(input) {
  const sheet = new Sheet()
  const lines = sheetLines(input)
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue
    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end += 1
    const written = line.slice(0, end)
    let start = end
    while (start < line.length && (line[start] === ' ' || line[start] === '\t')) start += 1
    const content = line.slice(start)
    const address = parseAddress(written)
    if (address === null) {
      throw new Failure(`line ${index + 1}: invalid cell address ${written.toUpperCase()}`)
    }
    if (sheet.has(address.key)) {
      throw new Failure(`line ${index + 1}: cell ${address.key} is declared twice`)
    }
    sheet.declare(address, content)
  }
  return sheet
}

function report(sheet, mode) {
  const out = []
  for (const cell of sheet.ordered()) {
    if (mode === 'values') {
      out.push(`${cell.address.key}=${formatValue(sheet.valueAt(cell.address.key))}\n`)
    } else {
      const names = sheet.dependencies(cell).map((name) => ` ${name}`)
      out.push(`${cell.address.key}:${names.join('')}\n`)
    }
  }
  return out.join('')
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : undefined
  if (mode !== 'values' && mode !== 'deps') throw new Failure('usage: cli.js values|deps')
  return report(readSheet(readStdin()), mode)
}

try {
  process.stdout.write(main(process.argv.slice(2)))
} catch (error) {
  if (!(error instanceof Failure)) throw error
  process.stderr.write(`error: ${error.message}\n`)
  process.exit(2)
}
"}

